<template><div class="card" style="padding:16px"><h3>Password Generator</h3><div style="font-size:22px;background:#111;padding:14px;border-radius:12px;word-break:break-all">{{pwd||'Generate a secure password'}}</div><p>Strength: <b>{{strength}}</b> — {{strengthHint}}</p><label>Type <select v-model="type"><option>Memorable Password</option><option>Random Password</option></select></label><br><label>Length: {{len}} {{type==='Memorable Password'?'words':'characters'}} <input type="range" min="5" max="32" v-model.number="len" /><button v-for="p in [5,15,18,25,32]" :key="p" @click="len=p">{{p}}</button></label><br><label>Capitalize <input type="checkbox" v-model="cap" /></label><div v-if="type==='Random Password'"><label><input type="checkbox" v-model="upper"/> Uppercase</label><label><input type="checkbox" v-model="lower"/> Lowercase</label><label><input type="checkbox" v-model="nums"/> Numbers</label><label><input type="checkbox" v-model="syms"/> Symbols</label></div><div style="display:flex;gap:8px;margin-top:12px"><button class="btn-primary" @click="generate">Generate Again</button><button @click="copy">{{copied?'Copied!':'Copy'}}</button><button @click="$emit('use',pwd)">Use This Password</button><button @click="$emit('close')">Close</button></div></div></template>
<script setup lang="ts">import {ref,computed} from 'vue'; import {passwordStrength} from '../lib/crypto'; const pwd=ref(''); const type=ref('Random Password'); const len=ref(18); const cap=ref(true); const upper=ref(true); const lower=ref(true); const nums=ref(true); const syms=ref(true); const copied=ref(false); const strength=ref('Medium'); const strengthHint=computed(()=>strength.value==='Strong'?'Great — hard to guess.':strength.value==='Medium'?'Okay, make it longer.':'Weak — generate a stronger one.'); async function generate(){ const res=await fetch(`http://localhost:8001/generate-password?type=${encodeURIComponent(type.value)}&length=${len.value}&upper=${upper.value}&lower=${lower.value}&numbers=${nums.value}&symbols=${syms.value}&capitalize=${cap.value}`); const d=await res.json(); pwd.value=d.password; strength.value=await passwordStrength(pwd.value) } function copy(){ navigator.clipboard.writeText(pwd.value); copied.value=true; setTimeout(()=>copied.value=false,1500) } generate();</script>
